// Kukicha Standard Library - Table
// Pretty-printed tables for CLI output with auto-aligned columns.
//
// Examples:
//
//	t := table.New(list of string{"Name", "Stars", "Language"})
//	t = t |> table.AddRow(list of string{"golang/go", "115000", "Go"})
//	t = t |> table.AddRowValues("rust-lang/rust", 98000, "Rust")   # cells stringified for you
//	t |> table.Print()
//
//	# With border style
//	t |> table.WithStyle(table.Style.Box) |> table.Print()
//
//	# Render to string for logging
//	s := table.ToString(t)
package table

import (
	"fmt"
	strpkg "kukicha.org/kukicha/stdlib/string"
	"kukicha.org/kukicha/stdlib/term"
	"strings"
)

// Style selects the border rendering style for a table.
// Set it with WithStyle; Print / ToString then honor it. Defaults to Plain.
type Style string

const (
	StylePlain    Style = "plain"
	StyleBox      Style = "box"
	StyleMarkdown Style = "markdown"
)

func AllStyle() []Style {
	return []Style{StylePlain, StyleBox, StyleMarkdown}
}

func ParseStyle(s string) (Style, error) {
	switch s {
	case "plain":
		return StylePlain, nil
	case "box":
		return StyleBox, nil
	case "markdown":
		return StyleMarkdown, nil
	}
	switch s {
	case "Plain":
		return StylePlain, nil
	case "Box":
		return StyleBox, nil
	case "Markdown":
		return StyleMarkdown, nil
	}
	var zero Style
	return zero, fmt.Errorf("invalid Style %q (valid: \"plain\", \"box\", \"markdown\")", s)
}

func (e Style) String() string {
	switch e {
	case StylePlain:
		return "Plain"
	case StyleBox:
		return "Box"
	case StyleMarkdown:
		return "Markdown"
	default:
		return string(e)
	}
}

// Table holds the headers, rows, and render style for a formatted table.
type Table struct {
	Headers []string
	Rows    [][]string
	Style   Style
}

// New creates a new table with the given column headers (Plain style by default).
// Example: t := table.New(list of string{"Name", "Age"})
func New(headers []string) Table {
	return Table{Headers: headers, Rows: [][]string{}, Style: StylePlain}
}

// AddRow appends a row of pre-stringified values to the table and returns the
// updated table. Cells must already be strings; for rows mixing numbers,
// bools, or other values use AddRowValues, which stringifies each cell.
// Rows with fewer columns than headers are padded with "".
// Example: t = t |> table.AddRow(list of string{"Alice", "30"})
func AddRow(t Table, row []string) Table {
	padded := make([]string, len(t.Headers))
	for i := range len(t.Headers) {
		if i < len(row) {
			padded[i] = row[i]
		}
	}
	t.Rows = append(t.Rows, padded)
	return t
}

// AddRowValues appends a row, rendering each cell with fmt.Sprint — no
// hand-stringifying numbers or bools (no interpolation ceremony) before
// adding them. Rows with fewer columns than headers are padded with "";
// cells beyond the header count are dropped.
// Example: t = t |> table.AddRowValues("go", 115000)
func AddRowValues(t Table, cells ...any) Table {
	padded := make([]string, len(t.Headers))
	for i := range len(t.Headers) {
		if i < len(cells) {
			padded[i] = fmt.Sprint(cells[i])
		}
	}
	t.Rows = append(t.Rows, padded)
	return t
}

// WithStyle sets the table's border style for chaining; Print / ToString honor it.
// Example: t |> table.WithStyle(table.Style.Markdown) |> table.Print()
func WithStyle(t Table, style Style) Table {
	t.Style = style
	return t
}

// Print prints the table to stdout with auto-aligned columns, using the table's style.
// Example: t |> table.Print()
func Print(t Table) {
	fmt.Println(renderTable(t, t.Style))
}

// ToString renders the table to a string using the table's style.
// Example: s := table.ToString(t)
func ToString(t Table) string {
	return renderTable(t, t.Style)
}

// renderTable is the internal rendering function.
// Column widths are computed from each cell's *visible* width — ANSI escape
// sequences (e.g. cells styled via stdlib/color) contribute zero columns,
// so colored cells align with plain ones of equal rendered width.
func renderTable(t Table, style Style) string {
	widths := make([]int, len(t.Headers))
	for i := range len(t.Headers) {
		widths[i] = term.VisibleWidth(t.Headers[i])
	}
	for _, row := range t.Rows {
		for i := range len(t.Headers) {
			if i < len(row) {
				w := term.VisibleWidth(row[i])
				if w > widths[i] {
					widths[i] = w
				}
			}
		}
	}
	out := strings.Builder{}
	switch style {
	case StyleMarkdown:
		out.WriteString(renderMarkdownRow(t.Headers, widths))
		out.WriteString(renderMarkdownSep(widths))
		for _, row := range t.Rows {
			out.WriteString(renderMarkdownRow(row, widths))
		}
	case StyleBox:
		out.WriteString(renderBoxTop(widths))
		out.WriteString(renderBoxRow(t.Headers, widths))
		out.WriteString(renderBoxMid(widths))
		for _, row := range t.Rows {
			out.WriteString(renderBoxRow(row, widths))
		}
		out.WriteString(renderBoxBottom(widths))
	case StylePlain:
		out.WriteString(renderPlainRow(t.Headers, widths))
		out.WriteString(renderPlainSep(widths))
		for _, row := range t.Rows {
			out.WriteString(renderPlainRow(row, widths))
		}
	}
	return out.String()
}

func renderPlainRow(cols []string, widths []int) string {
	sb := strings.Builder{}
	for i := range len(widths) {
		val := ""
		if i < len(cols) {
			val = cols[i]
		}
		sb.WriteString(term.PadRightVisible(val, widths[i]))
		if i < len(widths)-1 {
			sb.WriteString("  ")
		}
	}
	sb.WriteString("\n")
	return sb.String()
}

func renderPlainSep(widths []int) string {
	sb := strings.Builder{}
	for i := range len(widths) {
		sb.WriteString(strpkg.Repeat("-", widths[i]))
		if i < len(widths)-1 {
			sb.WriteString("  ")
		}
	}
	sb.WriteString("\n")
	return sb.String()
}

func renderMarkdownRow(cols []string, widths []int) string {
	sb := strings.Builder{}
	sb.WriteString("|")
	for i := range len(widths) {
		val := ""
		if i < len(cols) {
			val = cols[i]
		}
		sb.WriteString(fmt.Sprintf(" %v |", term.PadRightVisible(val, widths[i])))
	}
	sb.WriteString("\n")
	return sb.String()
}

func renderMarkdownSep(widths []int) string {
	sb := strings.Builder{}
	sb.WriteString("|")
	for i := range len(widths) {
		dashes := max(widths[i], 3)
		sb.WriteString(" ")
		sb.WriteString(strpkg.Repeat("-", dashes))
		sb.WriteString(" |")
	}
	sb.WriteString("\n")
	return sb.String()
}

func renderBoxTop(widths []int) string {
	sb := strings.Builder{}
	sb.WriteString("┌")
	for i := range len(widths) {
		sb.WriteString(strpkg.Repeat("─", widths[i]+2))
		if i < len(widths)-1 {
			sb.WriteString("┬")
		}
	}
	sb.WriteString("┐\n")
	return sb.String()
}

func renderBoxMid(widths []int) string {
	sb := strings.Builder{}
	sb.WriteString("├")
	for i := range len(widths) {
		sb.WriteString(strpkg.Repeat("─", widths[i]+2))
		if i < len(widths)-1 {
			sb.WriteString("┼")
		}
	}
	sb.WriteString("┤\n")
	return sb.String()
}

func renderBoxBottom(widths []int) string {
	sb := strings.Builder{}
	sb.WriteString("└")
	for i := range len(widths) {
		sb.WriteString(strpkg.Repeat("─", widths[i]+2))
		if i < len(widths)-1 {
			sb.WriteString("┴")
		}
	}
	sb.WriteString("┘\n")
	return sb.String()
}

func renderBoxRow(cols []string, widths []int) string {
	sb := strings.Builder{}
	sb.WriteString("│")
	for i := range len(widths) {
		val := ""
		if i < len(cols) {
			val = cols[i]
		}
		sb.WriteString(fmt.Sprintf(" %v │", term.PadRightVisible(val, widths[i])))
	}
	sb.WriteString("\n")
	return sb.String()
}
